let nombreArchivo = "";
try {
  const binaryData = $input.item.binary || {};
  const attachmentKey = Object.keys(binaryData).find(k => k.startsWith('attachment')) || null;
  const infoArchivo = attachmentKey ? binaryData[attachmentKey] : null;
  nombreArchivo = infoArchivo ? (infoArchivo.fileName || infoArchivo.filename || infoArchivo.name || "") : "";
} catch(e) {}
if (!nombreArchivo) {
  try {
    const emailBinary = $node["EmailRead Imap1"].binary || {};
    const emailKey = Object.keys(emailBinary).find(k => k.startsWith('attachment')) || null;
    const emailInfo = emailKey ? emailBinary[emailKey] : null;
    nombreArchivo = emailInfo ? (emailInfo.fileName || emailInfo.filename || emailInfo.name || "") : "";
  } catch(e) {}
}
if (!nombreArchivo) nombreArchivo = "Presupuesto_Sin_Titulo";
const tituloLimpio = nombreArchivo.replace(/\.[^/.]+$/, "").trim() || "Presupuesto";
const idUnico = tituloLimpio + "_" + Math.floor(Date.now() / 1000);
let emailRemitente = "Desconocido";
try {
  const from = $node["EmailRead Imap1"].json.from;
  if (typeof from === 'string') { const m = from.match(/<([^>]+)>/); emailRemitente = m ? m[1] : from; }
  else if (from?.value?.[0]?.address) { emailRemitente = from.value[0].address; }
  else if (from?.text) { const m = from.text.match(/<([^>]+)>/); emailRemitente = m ? m[1] : from.text; }
  else if (from?.address) { emailRemitente = from.address; }
} catch(e) { emailRemitente = "Desconocido"; }
const archivoTexto = $input.item.json.data || "";
const lines = archivoTexto.split(/\r?\n/);
const conceptos = {};
const relaciones = [];
for (const line of lines) {
  if (!line.trim()) continue;
  const parts = line.split('|');
  const tag = parts[0];
  if (tag === '~C') {
    const codigo = parts[1]?.trim() || "S/C";
    const unidad = parts[2]?.trim() || "";
    let precio = parseFloat(parts[4]?.replace(',', '.') || '0');
    conceptos[codigo] = { Capitulo: codigo, Unidad: unidad, Descripcion: parts[3]?.trim() || 'Sin descripcion', Precio: isNaN(precio) ? 0 : precio, conceptos: [] };
  } else if (tag === '~D') {
    const padre = parts[1]?.trim();
    let raw_hijos = parts[2] ? parts[2].trim() : '';
    if (raw_hijos.endsWith('\\')) raw_hijos = raw_hijos.slice(0, -1);
    const items = raw_hijos.split('\\');
    for (let i = 0; i < items.length; i += 3) {
      if (items[i]) relaciones.push([padre, items[i].trim(), parseFloat(items[i+1]?.replace(',', '.') || '1') * parseFloat(items[i+2]?.replace(',', '.') || '0')]);
    }
  }
}
const hijos = new Set();
for (const [p, h, q] of relaciones) {
  if (conceptos[p] && conceptos[h]) { conceptos[p].conceptos.push({ ...conceptos[h], Cantidad: q }); hijos.add(h); }
}
const filas = [];
const flatten = (arr) => {
  for (const c of arr) {
    if (!c.Capitulo) continue;
    filas.push({ propuesta_id: idUnico, texto_partida: (c.Capitulo || "S/C") + '::' + (c.Descripcion || "Sin descripcion"), unidad: c.Unidad || "", cantidad: c.Cantidad || 0, precio_base_estimado: c.Precio || 0 });
    if (c.conceptos && c.conceptos.length > 0) flatten(c.conceptos);
  }
};
const raices = Object.values(conceptos).filter(c => !hijos.has(c.Capitulo));
flatten(raices);
return [{ json: { propuesta_maestra: { Proyecto: idUnico, cliente: emailRemitente, estado: 'Pendiente', fecha_recepcion: new Date().toISOString() }, partidas_hijas: filas } }];

const allResults = [];
const fuentes = $('Parsear FIEBDC a JSON1').all();
for (const fuente of fuentes) {
  const partidas = Array.isArray(fuente.json?.partidas_hijas) ? fuente.json.partidas_hijas : [];
  for (const p of partidas) {
    if (!p || typeof p !== 'object' || !p.propuesta_id) continue;
    allResults.push({ json: { propuesta_id: String(p.propuesta_id), texto_partida: String(p.texto_partida || ''), unidad: String(p.unidad || ''), cantidad: Number(p.cantidad) || 0, precio_base_estimado: Number(p.precio_base_estimado) || 0 } });
  }
}
return allResults;

const wh = $('Webhook Local (Fase 4)').item.json.body;
const payload = {
  sender: { name: 'ADIR Reformas', email: 'adirbc3@gmail.com' },
  to: [{ email: wh.proveedor_email || '', name: wh.proveedor_nombre || '' }],
  subject: 'Solicitud de presupuesto - ' + (wh.oficio_solicitado || '') + ' | Proyecto ADIR',
  htmlContent: wh.html_email || ''
};
return [{ json: { _payload: JSON.stringify(payload) } }];

const solicitud = $("MySQL - Leer Solicitud").first()?.json;
if (!solicitud) { return [{ json: { html: '<html><body>Enlace no valido</body></html>' } }]; }
if (solicitud.estado_solicitud === 'Respondido') { return [{ json: { html: '<html><body>Solicitud Cerrada</body></html>' } }]; }
const partidas = $input.all().map(i => i.json);
const normalize = (str) => str ? str.trim().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "") : "";
const buscado = normalize(solicitud.oficio_solicitado);
const filtradas = partidas.filter(p => normalize(p.oficio_necesario) === buscado || normalize(p.oficio_asignado) === buscado);
let contentHtml = "";
if (filtradas.length === 0) {
  contentHtml = '<div>No hay partidas para: ' + solicitud.oficio_solicitado + '</div>';
} else {
  const filasHtml = filtradas.map(p => '<tr><td>' + (p.texto_partida || 'Sin descripcion') + '</td><td><input type="text" name="precio_' + p.id + '" required></td><td><input type="text" name="comentario_' + p.id + '"></td></tr>').join('');
  contentHtml = '<form action="https://n8n-production-f7f7.up.railway.app/webhook/fase5-procesar" method="POST"><input type="hidden" name="solicitud_id" value="' + solicitud.id + '"><input type="hidden" name="proveedor_id" value="' + (solicitud.proveedor_id || '') + '"><table>' + filasHtml + '</table><button type="submit">Enviar</button></form>';
}
const html = '<!DOCTYPE html><html><head><meta charset="utf-8"><title>Portal Proveedor</title></head><body><h1>Portal ADIR</h1>' + contentHtml + '</body></html>';
return [{ json: { html } }];

const body = $input.item.json.body;
const items = [];
for (const key of Object.keys(body)) {
  if (key.startsWith('precio_')) {
    const id = key.replace('precio_', '');
    const v = parseFloat((body[key] || "0").toString().replace(',', '.'));
    items.push({ json: { solicitud_id: body.solicitud_id, proveedor_id: body.proveedor_id || null, partida_id: id, precio_ofertado: isNaN(v) ? 0 : v, comentarios: body['comentario_' + id] || "" } });
  }
}
return items;

const wh = $input.item.json.body;
const payload = {
  sender: { name: 'ADIR Reformas', email: 'adirbc3@gmail.com' },
  to: [{ email: wh.cliente_email || '', name: wh.cliente_nombre || 'Cliente' }],
  subject: 'Presupuesto de Obra - ADIR Reformas | Proyecto ' + (wh.proyecto_nombre || wh.proyecto || ''),
  htmlContent: wh.html_presupuesto || ''
};
return [{ json: { _payload: JSON.stringify(payload) } }];

const body = $input.item.json.body;
const precios = body.precios || [];
const solicitud_id = body.solicitud_id;
const proveedor_id = body.proveedor_id || null;
if (!precios.length) return [];
return precios.map(p => ({ json: { solicitud_id, proveedor_id, partida_id: p.partida_id, precio_ofertado: parseFloat(p.precio_ofertado) || 0, comentarios: p.comentarios || "" } }));
